-- Rebrand all customer/vendor-facing email templates to the new purple-gradient
-- design system (logo + wordmark header, hero icon circle, colored info boxes,
-- numbered steps, "Need Help?" footer). Supersedes the narrower first pass in
-- 20260914010000_brand_vendor_shipment_ready_templates.sql, which only covered
-- the two Vendor Shipment Ready templates.
--
-- Only html_content is touched; subject/text_content are unchanged.
-- html_content is pushed base64-encoded to avoid SQL quote-escaping issues
-- with embedded HTML attribute quotes.

update email_templates set html_content = convert_from(decode('','base64'),'UTF8') where name = 'Vendor Shipment Ready Fez Pickup';
update email_templates set html_content = convert_from(decode('','base64'),'UTF8') where name = 'Vendor Shipment Ready Fez Hub';
